233	    @Test
234	    public void testOverwriteAcksAndRetriesForIdempotentProducers() {
235	        Properties props = new Properties();
236	        props.setProperty(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9999");
237	        props.setProperty(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "transactionalId");
238	        props.setProperty(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
239	        props.setProperty(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
240	
241	        ProducerConfig config = new ProducerConfig(props);
242	        assertTrue(config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG));
243	        assertTrue(Stream.of("-1", "all").anyMatch(each -> each.equalsIgnoreCase(config.getString(ProducerConfig.ACKS_CONFIG))));
244	        assertEquals(Integer.MAX_VALUE, (int) config.getInt(ProducerConfig.RETRIES_CONFIG));
245	        assertTrue(config.getString(ProducerConfig.CLIENT_ID_CONFIG).equalsIgnoreCase("producer-" +
246	                config.getString(ProducerConfig.TRANSACTIONAL_ID_CONFIG)));
247	    }
