249	    @Test
250	    public void testAcksAndIdempotenceForIdempotentProducers() {
251	        Properties baseProps = baseProperties();
252	
253	        Properties validProps = new Properties() {{
254	                putAll(baseProps);
255	                setProperty(ProducerConfig.ACKS_CONFIG, "0");
256	                setProperty(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "false");
257	            }};
258	        ProducerConfig config = new ProducerConfig(validProps);
259	        assertFalse(
260	            config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG),
261	            "idempotence should be overwritten");
262	        assertEquals(
263	            "0",
264	            config.getString(ProducerConfig.ACKS_CONFIG),
265	            "acks should be overwritten");
266	
267	        Properties validProps2 = new Properties() {{
268	                putAll(baseProps);
269	                setProperty(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "transactionalId");
270	            }};
271	        config = new ProducerConfig(validProps2);
272	        assertTrue(
273	            config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG),
274	            "idempotence should be set with the default value");
275	        assertEquals(
276	            "-1",
277	            config.getString(ProducerConfig.ACKS_CONFIG),
278	            "acks should be set with the default value");
279	
280	        Properties validProps3 = new Properties() {{
281	                putAll(baseProps);
282	                setProperty(ProducerConfig.ACKS_CONFIG, "all");
283	                setProperty(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "false");
284	            }};
285	        config = new ProducerConfig(validProps3);
286	        assertFalse(config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG),
287	            "idempotence should be overwritten");
288	        assertEquals(
289	            "-1",
290	            config.getString(ProducerConfig.ACKS_CONFIG),
291	            "acks should be overwritten");
292	
293	        Properties validProps4 = new Properties() {{
294	                putAll(baseProps);
295	                setProperty(ProducerConfig.ACKS_CONFIG, "0");
296	            }};
297	        config = new ProducerConfig(validProps4);
298	        assertFalse(
299	            config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG),
300	            "idempotence should be disabled when acks not set to all and `enable.idempotence` config is unset.");
301	        assertEquals(
302	            "0",
303	            config.getString(ProducerConfig.ACKS_CONFIG),
304	            "acks should be set with overridden value");
305	
306	        Properties validProps5 = new Properties() {{
307	                putAll(baseProps);
308	                setProperty(ProducerConfig.ACKS_CONFIG, "1");
309	            }};
310	        config = new ProducerConfig(validProps5);
311	        assertFalse(
312	            config.getBoolean(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG),
313	            "idempotence should be disabled when acks not set to all and `enable.idempotence` config is unset.");
314	        assertEquals(
315	            "1",
316	            config.getString(ProducerConfig.ACKS_CONFIG),
317	            "acks should be set with overridden value");
318	
319	        Properties invalidProps = new Properties() {{
320	                putAll(baseProps);
321	                setProperty(ProducerConfig.ACKS_CONFIG, "0");
322	                setProperty(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "false");
323	                setProperty(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "transactionalId");
324	            }};
325	        assertThrows(
326	            ConfigException.class,
327	            () -> new ProducerConfig(invalidProps),
328	            "Cannot set a transactional.id without also enabling idempotence");
329	
330	        Properties invalidProps2 = new Properties() {{
331	                putAll(baseProps);
332	                setProperty(ProducerConfig.ACKS_CONFIG, "1");
333	                // explicitly enabling idempotence should still throw exception
334	                setProperty(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");
335	            }};
336	        assertThrows(
337	            ConfigException.class,
338	            () -> new ProducerConfig(invalidProps2),
339	            "Must set acks to all in order to use the idempotent producer");
340	
341	        Properties invalidProps3 = new Properties() {{
342	                putAll(baseProps);
343	                setProperty(ProducerConfig.ACKS_CONFIG, "0");
344	                setProperty(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "transactionalId");
345	            }};
346	        assertThrows(
347	            ConfigException.class,
348	            () -> new ProducerConfig(invalidProps3),
349	            "Must set acks to all when using the transactional producer.");
350	    }
