388	            }};
389	        assertThrows(
390	            ConfigException.class,
391	            () -> new ProducerConfig(invalidProps),
392	            "Cannot set a transactional.id without also enabling idempotence");
393	
394	        Properties invalidProps2 = new Properties() {{
395	                putAll(baseProps);
396	                setProperty(ProducerConfig.RETRIES_CONFIG, "0");
397	                // explicitly enabling idempotence should still throw exception
