405	        Properties invalidProps3 = new Properties() {{
406	                putAll(baseProps);
407	                setProperty(ProducerConfig.RETRIES_CONFIG, "0");
408	                setProperty(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "transactionalId");
409	            }};
410	        assertThrows(
411	            ConfigException.class,
412	            () -> new ProducerConfig(invalidProps3),
413	            "Must set retries to non-zero when using the transactional producer.");
414	    }
