696	    public void shouldCloseProperlyAndThrowIfInterrupted() throws Exception {
697	        Map<String, Object> configs = new HashMap<>();
698	        configs.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9999");
699	        configs.put(ProducerConfig.PARTITIONER_CLASS_CONFIG, MockPartitioner.class.getName());
700	        configs.put(ProducerConfig.BATCH_SIZE_CONFIG, "1");
701	
702	        Time time = new MockTime();
703	        MetadataResponse initialUpdateResponse = RequestTestUtils.metadataUpdateWith(1, singletonMap("topic", 1));
704	        ProducerMetadata metadata = newMetadata(0, 0, Long.MAX_VALUE);
705	        MockClient client = new MockClient(time, metadata);
706	        client.updateMetadata(initialUpdateResponse);
707	
708	        final Producer<String, String> producer = kafkaProducer(configs, new StringSerializer(),
709	                new StringSerializer(), metadata, client, null, time);
710	
711	        ExecutorService executor = Executors.newSingleThreadExecutor();
712	        final AtomicReference<Exception> closeException = new AtomicReference<>();
713	        try {
714	            Future<?> future = executor.submit(() -> {
715	                producer.send(new ProducerRecord<>("topic", "key", "value"));
716	                try {
717	                    producer.close();
718	                    fail("Close should block and throw.");
719	                } catch (Exception e) {
720	                    closeException.set(e);
721	                }
722	            });
723	
724	            // Close producer should not complete until send succeeds
725	            try {
726	                future.get(100, TimeUnit.MILLISECONDS);
727	                fail("Close completed without waiting for send");
728	            } catch (java.util.concurrent.TimeoutException expected) { /* ignore */ }
729	
730	            // Ensure send has started
731	            client.waitForRequests(1, 1000);
732	
733	            assertTrue(future.cancel(true), "Close terminated prematurely");
734	
735	            TestUtils.waitForCondition(() -> closeException.get() != null,
736	                    "InterruptException did not occur within timeout.");
737	
738	            assertInstanceOf(InterruptException.class, closeException.get(), "Expected exception not thrown " + closeException);
739	        } finally {
740	            executor.shutdownNow();
741	        }
