1250	                                                          Map<TopicPartition, OffsetAndMetadata> offsets,
1251	                                                          ConsumerGroupMetadata groupMetadata) {
1252	        // Resolve topic ids from the metadata cache at request build time.
1253	        // KafkaProducer.sendOffsetsToTransaction has already ensured the cache
1254	        // is fresh for these topics, so this is a non-blocking lookup.
1255	        var topicIds = metadata.topicIds();
1256	        var requestTopicsByName = new HashMap<String, TxnOffsetCommitRequestTopic>();
1257	        var topicNamesByIds = new HashMap<Uuid, String>();
1258	        var topics = new ArrayList<TxnOffsetCommitRequestTopic>();
1259	        var allHaveTopicIds = true;
1260	        for (var entry : offsets.entrySet()) {
1261	            var tp = entry.getKey();
1262	            var offsetAndMetadata = entry.getValue();
1263	            pendingTxnOffsetCommits.put(
1264	                tp,
1265	                new CommittedOffset(
1266	                    offsetAndMetadata.offset(),
1267	                    offsetAndMetadata.metadata(),
1268	                    offsetAndMetadata.leaderEpoch()
1269	                )
1270	            );
1271	            var topicId = topicIds.getOrDefault(tp.topic(), Uuid.ZERO_UUID);
1272	            allHaveTopicIds &= !topicId.equals(Uuid.ZERO_UUID);
1273	            var topic = requestTopicsByName.computeIfAbsent(tp.topic(), name -> {
1274	                var t = new TxnOffsetCommitRequestTopic().setName(name).setTopicId(topicId);
1275	                topics.add(t);
1276	                if (!topicId.equals(Uuid.ZERO_UUID)) {
1277	                    topicNamesByIds.put(topicId, name);
1278	                }
1279	                return t;
