1285	                .setCommittedMetadata(offsetAndMetadata.metadata()));
1286	        }
1287	
1288	        var data = new TxnOffsetCommitRequestData()
1289	            .setTransactionalId(transactionalId)
1290	            .setGroupId(groupMetadata.groupId())
1291	            .setProducerId(producerIdAndEpoch.producerId)
1292	            .setProducerEpoch(producerIdAndEpoch.epoch)
