public void sendOffsetsToTransaction(Map<TopicPartition, OffsetAndMetadata> offsets,
                                     ConsumerGroupMetadata groupMetadata) throws ProducerFencedException {
    throwIfInvalidGroupMetadata(groupMetadata);
    throwIfNoTransactionManager();
    throwIfProducerClosed();
    throwIfInPreparedState();

    if (!offsets.isEmpty()) {
        long start = time.nanoseconds();
        long nowMs = time.milliseconds();
        try {
            // Ensure metadata for all topics in the offsets is fresh (KIP-1319).
            // This allows the producer to include topic IDs in the TxnOffsetCommit request,
            // enabling negotiation of v6+ which aligns with OffsetCommit API.
            for (TopicPartition tp : offsets.keySet()) {
                waitOnMetadata(tp.topic(), null, nowMs, maxBlockTimeMs);
            }
        } catch (InterruptedException e) {
            throw new InterruptException(e);
        }
        TransactionalRequestResult result = transactionManager.sendOffsetsToTransaction(offsets, groupMetadata);
        sender.wakeup();
        result.await(maxBlockTimeMs, TimeUnit.MILLISECONDS, SEND_OFFSETS_TIMEOUT_MSG);
        producerMetrics.recordSendOffsets(time.nanoseconds() - start);
    }
}

